    27  /* This map associates each of the parameters with the string
    28     representation of the parameter's name */
    29  struct vcardparameter_kind_map
    30  {
    31      vcardparameter_kind kind;
    32      const char *name;
    33
    34      vcardvalue_kind value_kind;
    35      unsigned int flags;
    36  };
