   120  vcardparameter_kind vcardparameter_string_to_kind(const char *string)
   121  {
   122      struct vcardparameter_kind_map key = {0};
   123      struct vcardparameter_kind_map *result;
   124
   125      if (string == 0) {
   126          return VCARD_NO_PARAMETER;
   127      }
   128
   129      key.kind = VCARD_ANY_PARAMETER;
   130      key.name = string;
   131      result =
   132          bsearch(&key, parameter_map, sizeof(parameter_map) / sizeof(struct vcardparameter_kind_map),
   133                  sizeof(struct vcardparameter_kind_map),
   134                  (int (*)(const void *, const void *))vcardparameter_compare_kind_map);
   135
   136      if (result) {
   137          return result->kind;
   138      }
   139
   140      if (strncmp(string, "X-", 2) == 0) {
   141          return VCARD_X_PARAMETER;
   142      }
   143
