   152  vcardvalue_kind vcardparameter_value_to_value_kind(vcardparameter_value value)
   153  {
   154      int i;
   155
   156      for (i = 0; value_kind_map[i].kind != VCARD_NO_VALUE; i++) {
   157
   158          if (value_kind_map[i].value == value) {
   159              return value_kind_map[i].kind;
   160          }
   161      }
   162
   163      return VCARD_NO_VALUE;
   164  }
