   166  const char *vcardparameter_enum_to_string(int e)
   167  {
   168      int i, num_params;
   169
   170      icalerror_check_arg_rz(e >= VCARDPARAMETER_FIRST_ENUM, "e");
   171      icalerror_check_arg_rz(e <= VCARDPARAMETER_LAST_ENUM, "e");
   172
   173      num_params = (int)(sizeof(vcardparameter_map) / sizeof(vcardparameter_map[0]));
   174      for (i = 0; i < num_params; i++) {
   175          if (e == vcardparameter_map[i].enumeration) {
   176              return vcardparameter_map[i].str;
   177          }
   178      }
   179
   180      return 0;
   240  }
