   242  void vcardparameter_add_value_from_string(vcardparameter *param,
   243                                            const char *val)
   244  {
   245      icalerror_check_arg_rv((param != 0 && param->is_multivalued != 0), "param");
   246      icalerror_check_arg_rv((val != 0), "val");
   247
   248      if (param->value_kind == VCARD_TEXT_VALUE) {
   249          if (param->values == 0) {
   250              param->values = vcardstrarray_new(5);
   251          }
   252
   253          vcardstrarray_add(param->values, val);
   254
   255      } else {
   256          /* Search through the parameter map to find a matching kind */
   257          int enumeration = _vcardparameter_string_to_enum(val, param->kind);
   258          vcardenumarray_element e = { enumeration, NULL };
   259
   260          if (enumeration == 0) {
   261              /* The kind was in the parameter map, but the string did not
   262                 match, so assume that it is an alternate value, like an
   263                 X-value. */
   264              e.xvalue = (char *) val;
   265          }
   266
   267          if (param->values == 0) {
   268              param->values = vcardenumarray_new(5);
   269          }
   270
   271          vcardenumarray_add(param->values, &e);
   272      }
   273  }
