   275  vcardparameter *vcardparameter_new_from_value_string(vcardparameter_kind kind,
   276                                                       const char *val)
   277  {
   278      struct vcardparameter_impl *param = 0;
   279
   280      icalerror_check_arg_rz((val != 0), "val");
   281
   282      param = vcardparameter_new_impl(kind);
   283      if (!param) {
   284          return 0;
   285      }
   286
   287      vcardparameter_set_value_from_string(param, val);
   288
   289      return param;
   290  }
